inline SkipColor SkipColorOf(float r, float g, float b, float a) {
    SkipColor c;
    c.clear = true;
    const float v[4] = {r, g, b, a};
    for (int i = 0; i < 4; ++i) {
        if (v[i] == 0.0f) continue;
        if (v[i] != 1.0f) { c.valid = false; c.rgba = 0; return c; }
        c.rgba |= 0xFFu << (8 * i);
    }
    c.valid = true;
    return c;
}
