        StageLog("hitch33-targets: stage %08x left: render targets made in VISIBLE frames %u (those frames %.0f ms; target 0), behind closed screens %u, of them made ahead by "
                 "GXV_POOLPRIME %u; wish list %u sizes (GXV_POOLPRIME=%d)", stage, c.visTargets, c.visTargetMs, c.shutTargets, c.primed, PoolWishCount(), PoolPrimeOn() ? 1 : 0);
    if (port_log_summary && c.wipeFrames)
        StageLog("hitch33-wipe: stage %08x left: frames with a moving wipe 90 %% closed or more: %u (%.0f ms), over 50 ms %u, worst %.0f ms; in them: links %u (%.0f ms), warm-up and "
                 "queue work %.0f ms, frame starts of 20 ms or more %u (GXV_WIPE_GUARD=%d: targets over 50 ms 0, links 0)", stage, c.wipeFrames, c.wipeMs, c.wipeOver, c.wipeWorstMs,
                 c.wipeLinks, c.wipeLinkMs, c.wipeWorkMs, c.wipeStarts, WipeGuardOn() ? 1 : 0);
