// (plane37: GXV_HRW36_PLANE_GATE reads the first picture's depth while the second is drawn, as the fresh player's draws test against it: its last scene stores it)
std::atomic<unsigned> g_noFreshDepthReads{0};
bool WantsDepth() {
    if (!g_w.armed) return false;
    if (BoxDepthEnv() && keepd::Mode() == 1 && DepthEnv() >= 3) return true;  // (keepdepth31: the second picture's box reads the depth the first picture kept)
    const bool fresh = FreshEnv();
    if (fresh && !g_w.noFresh) return true;
    // (c183fix F6b) the detail mask is made mid-picture at the game's marker (PlanFrame's markedOnly path: MaskMid), never from the depth at the display copy:
    // that path never sets g_hrwMaskAtCopy, the only way Snapshot makes a mask there. So the detail mask is not a reader of the depth at the copy, and a frozen
    // plain pair keeps C182's saving (the last scene need not store its depth). The plane gate's copy-time mask stays covered by the `plane` term.
    const bool need = hrwpair::NeedsDepth(true, WantsSnapDepth(), fresh, g_w.noFresh,
                                         PlaneEnv() > 0 && PlaneGateEnv() > 0, false);
    if (!need && fresh) g_noFreshDepthReads.fetch_add(1, std::memory_order_relaxed);
    return need;
}
