// GXV_DIRECT_DISPLAY (vgx_cmd.h): the host's present hook asks, in its whole-present phase, whether the picture can be shown by flipping the EFB's
// own colour buffer. Returns that buffer's texture name (the host arms vglSetNextFlip with it) or 0 (the present as today).
unsigned DirectDisplayOffer(int x, int y, int w, int h, int dx0, int dx1, int screenW, int screenH, bool hostOk) {
    if (directd::Mode() != 1) return 0;
    vgx::dd::Machine<directd::World>& m = directd::M();
    if (directd::g_makeFailed && !m.selfOff) { m.selfOff = true; m.DropSuccessor(); }
    if (m.selfOff) directd::GoOff();
    if (directd::g_off && m.InFlight() == 0 && m.Next() == 0) { directd::NoteOffPicture(); directd::g_offered = false; return 0; } // (off and holding nothing: no cost)
    vgx::dd::Inputs in;
    in.mode = 1;
    in.api = directd::Api();
    in.keepRt = KeepRenderTargets();
    in.x = x; in.y = y; in.w = w; in.h = h;
    in.rtW = g_rtW; in.rtH = g_rtH;
    in.screenW = screenW; in.screenH = screenH; in.dx0 = dx0; in.dx1 = dx1;
    in.samples = g_efbSamples;
    in.hudEngaged = hudn::g_hud.engaged;
    in.phaseZero = hudn::g_hud.phase == 0;
    in.capture = g_capture || g_skipDraws;
    in.hostOk = hostOk;
    if (directd::Dyn()) { // (dd24) a pair held by the game thread (engaged or wanted), drawn now (a first or a second picture), or less than kHrwLead presents back: the old present
        ++directd::g_presents;
        const bool pairPic = warp31::g_w.armed || g_hrwBPicture || hrwbe::g_retain || hrwbe::g_replay;
        if (pairPic) directd::g_lastPair = directd::g_presents;
        const bool gameHold = port_hrw_dd_hold && port_hrw_dd_hold() != 0;
        in.hrwHold = vgx::dd::HrwHold(gameHold, pairPic, directd::g_presents, directd::g_lastPair);
    }
    const CopyDispCmd* d = g_charaDisp;
    if (d) {
        // the copy's own clear: the whole EFB, colour and alpha (what ClearEfb does with it); then the old picture is not needed by the next one
        const float sx = ScaleX(), sy = ScaleY();
        const int x0 = Rnd(d->src.x * sx), y0 = Rnd(d->src.y * sy), x1 = Rnd((d->src.x + d->src.w) * sx), y1 = Rnd((d->src.y + d->src.h) * sy);
        in.haveCopy = true;
        in.clearEnable = d->clear.enable;
        in.clearColor = d->clear.color ? 1 : 0; in.clearAlpha = d->clear.alpha ? 1 : 0; in.clearDepth = d->clear.depth ? 1 : 0; in.clearElided = d->clearElided ? 1 : 0;
        in.clearWhole = d->clear.enable && d->clear.color && d->clear.alpha && x0 <= 0 && y0 <= 0 && x1 >= g_rtW && y1 >= g_rtH;
        in.chara = d->charaN != 0 || g_charaFull;
        in.edgeAA = EdgeAAWanted(w, h, dx1 - dx0, screenH);
    }
    in.sharpen = SharpenAmount(w, h, dx1 - dx0, screenH);
    in.planOn = dplan::Enabled() || EfbSwapEnabled(); // (what proves a later picture's start overwrites the colour whole: PlanFrame's liveness)
    directd::g_cleared = in.clearWhole;
    directd::g_offered = true;
    directd::g_reported = directd::g_flipped = false;
    vgx::dd::Reason why = vgx::dd::kHost;
    const bool disp = g_efbColor != 0 && vglIsDisplayTexture && vglIsDisplayTexture(g_efbColor) != 0;
    const unsigned r = m.Offer(in, g_efbColor, disp, &why);
    m.census.dynDenied = directd::g_dynDenied; m.census.dynRefused = directd::g_dynRefused;
    m.census.dynReturned = directd::g_dynReturned;
    // (dd24) the drain the game thread waits for before it opens a pair: while held nothing is flipped and every buffer in flight has gone back (Offer ages them first)
    // (fix24) "drained" is not only the two-pictures count of Age(): the flipped buffer may still be on the display for latency 4-5. Quiet is published only kHrwLead presents (the margin the other
    // direction uses) after the last flip offered, and the buffers in flight are back.
    if (directd::Dyn()) {
        if (r != 0) directd::g_lastFlip = directd::g_presents;
        directd::g_quiet.store(in.hrwHold && r == 0 && m.InFlight() == 0 && directd::g_presents >= directd::g_lastFlip + vgx::dd::kHrwLead ? 1 : 0, std::memory_order_relaxed);
    }
    return r;
}
// The host's answer: the picture was shown by the flip (flipped) or the old way (why = vgx::dd::Reason as int, e.g. kRefused). The rotation itself
// is made when the hook returns (CopyDisp: directd::Commit), with the EFB bound again.
void DirectDisplayResult(bool flipped, int why) {
    directd::g_reported = true;
    directd::g_flipped = flipped;
    directd::g_why = static_cast<vgx::dd::Reason>(why);
}
