    out[kHudNativeReasons + 2] = H.lost;                          // (hud56: pictures whose 2D draws were drawn by neither path: must be 0)
    out[kHudNativeReasons + 3] = H.pairANative + H.swapMissed;    // (hud56: a pair's first picture taken natively, or a native tail whose swap did not run: must be 0)
