// (GXV_STAGEWARM_HOLD_MS) for GameSystemSceneController::isReadyToStartScene (weak there): 1 = the stage's warm-up queue is not done, wait a frame.
extern "C" int port_stage_warm_hold(void) { return vgx::backend::StageWarmHold(); }
// hitch33 5a (GXV_WIPE_OPEN_HOLD): the game thread, from WipeFade::control / WipeRing::exeWipeIn while the opening wipe is still at its first step (fully closed). 1 = stay closed
// this turn. See g_h33OpenArmed. Only the first opening after a stage load is held; everything else answers 0 at once.
// hitch33 9 (GXV_WIPE_OPEN_NOWIPE, default 1; 0 = 6a): the game thread, GameScene::startStagePlayFirst, for a stage that begins without an opening wipe: is a hold armed (a
// stage load has just ended)? No side effect: the hold itself starts when the fade it then opens asks port_wipe_open_hold.
// hitch33 14: the same question with the place that asks (the trace names it). Sites: 1 GameScene::startStagePlayFirst with an opening camera, 2 with a scenario
// starter, 3 "begin without wipe", 4 GameSceneScenarioOpeningCameraState::start (the opening camera's own start, which forced the fade open: the path Honeyhive takes),
// 5 a start with a wipe of its own (trace only: the answer is not used and nothing is counted), 0 the old entry.
extern "C" int port_wipe_open_site(int site) {
    using namespace vgx::backend;
    static const bool on = vgx::EnvInt("GXV_WIPE_OPEN_HOLD", 1) != 0 && vgx::EnvInt("GXV_WIPE_OPEN_NOWIPE", 1) != 0;
    static const bool cameraOn = vgx::EnvInt("GXV_WIPE_OPEN_CAMERA", 1) != 0; // (14: site 4; 0 = c140, the opening camera forces the fade open)
    const bool armed = H33OpenArmed();
    const bool loading = port_scene_loading_active && port_scene_loading_active() != 0;
    const int answer = (on && armed && !loading && site != 5 && (site != 4 || cameraOn)) ? 1 : 0;
    if (H33OpenTraceOn() && port_log_summary) {
        static const char* const kSite[] = {"unnamed", "stage start with an opening camera", "stage start with a scenario starter", "stage start without a wipe",
                                            "the opening camera's own start (it forces the fade open)", "stage start with a wipe of its own (not asked, trace only)"};
        port_log_summary("hitch33-open-trace: stage %08x: hook '%s' called: scene serial %u, serial that had its hold %u, armed %s, loading %d, hold in progress %s -> %s",
                         port_scene_key ? port_scene_key() : 0u, kSite[site >= 0 && site <= 5 ? site : 0], port_scene_serial ? port_scene_serial() : 0u,
                         g_h33OpenDoneSerial.load(std::memory_order_relaxed), armed ? "yes" : "no", loading ? 1 : 0,
                         g_h33OpenFirstMs.load(std::memory_order_relaxed) > 0.0 ? "yes" : "no",
                         site == 5 ? "nothing changed" : answer ? "the black fade is closed and held for the first pictures" : "the game's own start, nothing held");
    }
    if (answer && site != 4) g_h33OpenNoWipe.fetch_add(1, std::memory_order_relaxed); // (site 4 follows site 1 in the same start: counted once)
    return answer;
}
extern "C" int port_wipe_open_armed(void) { return port_wipe_open_site(0); }
extern "C" int port_wipe_open_hold(void) {
    using namespace vgx::backend;
    static const bool on = vgx::EnvInt("GXV_WIPE_OPEN_HOLD", 1) != 0;
    if (!on || !H33OpenArmed()) return 0;
    if (port_scene_loading_active && port_scene_loading_active() != 0) { // (a wipe that opens over a running load, the star select's: never held)
        static uint32_t toldSerial = 0; // (14: once a scene)
        const uint32_t serial = port_scene_serial ? port_scene_serial() : 0u;
        if (H33OpenTraceOn() && port_log_summary && serial != toldSerial) {
            toldSerial = serial;
            port_log_summary("hitch33-open-trace: stage %08x: an opening wipe asked while the load is running (scene serial %u): not held", port_scene_key ? port_scene_key() : 0u, serial);
        }
        return 0;
    }
    static const double capMs = static_cast<double>(std::max(0L, vgx::EnvInt("GXV_WIPE_OPEN_CAP_MS", 2000)));
    static const uint32_t need = static_cast<uint32_t>(std::max(1L, vgx::EnvInt("GXV_WIPE_OPEN_CALM", 3)));
    static const double lightMs = static_cast<double>(std::max(1L, vgx::EnvInt("GXV_WIPE_OPEN_MS", 40)));
    // (hitch33 6a, GXV_WIPE_OPEN_QUEUE, default 1; 0 = 5a) The stage queue of a load whose closed-screen hold was suppressed (midhold: a scene change without a star select, the
    // tour jump) was worked off behind play: console batch 4 (c118), Honeyhive: "47 slices, 64 links, 570 ms in all (12.13 ms a slice, budget 2.0 ms)", listed as 2-5 "program
    // links" hitches of 50-117 ms a stage. The opening wipe now also stays closed while that queue has entries left (the held frames are not live, so its slices run in them),
    // inside the same cap.
    static const bool queueOn = vgx::EnvInt("GXV_WIPE_OPEN_QUEUE", 1) != 0;
    static double firstMs = 0, lastMs = 0, worstTurnMs = 0;
    static unsigned turns = 0, calmTurns = 0, queueAtStart = 0;
    const double now = NowMs();
    const unsigned queueLeft = queueOn ? g_stageLeft.load(std::memory_order_relaxed) : 0u;
    if (firstMs <= 0.0 || now - lastMs > 1000.0) { // (a new hold)
        firstMs = now; lastMs = now; turns = 0; calmTurns = 0; worstTurnMs = 0; queueAtStart = queueLeft;
        g_h33OpenEpoch.fetch_add(1, std::memory_order_relaxed);
        g_h33OpenHoldMs.store(now, std::memory_order_relaxed);
        g_h33OpenFirstMs.store(now, std::memory_order_relaxed);
        g_h33OpenTurns.store(0, std::memory_order_relaxed);
        if (H33OpenTraceOn() && port_log_summary)
            port_log_summary("hitch33-open-trace: stage %08x: an opening wipe asked for the first time (scene serial %u): the hold begins, stage queue entries left %u",
                             port_scene_key ? port_scene_key() : 0u, port_scene_serial ? port_scene_serial() : 0u, queueLeft);
        return 1;
    }
    const double dt = now - lastMs;
    lastMs = now;
    ++turns;
    g_h33OpenTurns.store(turns, std::memory_order_relaxed);
    if (dt > worstTurnMs) worstTurnMs = dt;
    calmTurns = dt <= 40.0 ? calmTurns + 1 : 0;
    const double t0 = g_h33FrameT0.load(std::memory_order_relaxed);
    const bool busyNow = t0 > 0.0 && now - t0 >= lightMs; // (the back end is inside a long frame right now)
    const uint32_t light = g_h33OpenLight.load(std::memory_order_relaxed);
    const bool calm = light >= need && calmTurns >= need && !busyNow && queueLeft == 0;
    const bool cap = now - firstMs >= capMs;
    if (!calm && !cap) { g_h33OpenHoldMs.store(now, std::memory_order_relaxed); return 1; }
    H33OpenDone();
    g_h33OpenHoldMs.store(0.0, std::memory_order_relaxed);
    g_h33OpenFirstMs.store(0.0, std::memory_order_relaxed);
    if (port_log_summary)
        port_log_summary("hitch33-open: stage %08x: the opening wipe was held closed %.0f ms (%u turns) for the stage's first pictures: %u heavy pictures behind it (worst %u ms), "
                         "longest game turn %.0f ms; stage queue entries left: %u at its start, %u now; let go: %s; stage starts without a wipe given the black fade so far: %u (GXV_WIPE_OPEN_HOLD=1; target: 'hitch33-wipe' over 50 ms 0)",
                         port_scene_key ? port_scene_key() : 0u, now - firstMs, turns, g_h33OpenHeavy.load(std::memory_order_relaxed),
                         g_h33OpenWorstMs.load(std::memory_order_relaxed), worstTurnMs, queueAtStart, queueLeft, calm ? "the pictures are light" : "THE CAP (GXV_WIPE_OPEN_CAP_MS)",
                         g_h33OpenNoWipe.load(std::memory_order_relaxed));
    firstMs = 0;
    return 0;
}
